<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{ $letter->letter_number ?? 'Draft Letter' }}</title>
    <style>
        html, body {
            width: 100%;
            min-height: 100%;
            margin: 0;
            padding: 0;
        }
        body {
            font-family: 'Times New Roman', Times, serif;
            line-height: 1.5;
            padding: 2cm; /* Standard margin */
            box-sizing: border-box;
            position: relative;
        }
        .header-container {
            display: flex;
            align-items: center;
            justify-content: center;
            border-bottom: 5px double black;
            padding-bottom: 10px;
            margin-bottom: 2rem;
        }
        .logo {
            width: 200px;
            margin-right: 2rem;
        }
        .church-info {
            text-align: center;
            line-height: 1;
        }
        .church-info h1 {
            margin: 0;
            font-size: 24px;
            font-weight: bold;
            font-family: 'Times New Roman', serif;
            text-transform: uppercase;
        }
        .church-info h2 {
            margin: 5px 0;
            font-size: 28px;
            font-weight: bold;
            font-family: 'Times New Roman', serif;
            text-transform: uppercase;
        }
        .church-info p {
            margin: 2px 0;
            font-size: 14px;
        }
        .content {
            text-align: justify;
            min-height: 300px; /* Minimum content height */
        }
        .footer {
            margin-top: 3rem;
            /* Ensure footer doesn't overlap with QR code if content is long */
            margin-bottom: 3rem; 
        }
        .signature-section {
            display: flex;
            justify-content: space-between;
            margin-top: 2rem;
        }
        .signer {
            text-align: center;
            width: 40%;
        }
        .qr-code {
            position: absolute;
            bottom: 2cm;
            right: 2cm;
            opacity: 0.8;
            /* Ensure it stays on top or correct layer */
            z-index: 5;
        }
        @media print {
            html, body {
                height: 100%;
            }
            body {
                padding: 0;
            }
            @page {
                margin: 2cm;
                size: auto;
            }
            /* When using @page margin, the body matches the print area. 
               Absolute 0,0 is bottom-right of print area. */
            .qr-code {
                bottom: 0;
                right: 0;
            }
        }
    </style>
</head>
<body>
