        <div class="church-info">
            <h1>GEREJA PRESBITERIAN INJILI INDONESIA</h1>
            <p>Terdaftar: DEPAG RI. No. 174 tahun 1991</p>
            <p>Her Registrasi: DJ III/KEP/HK. 005/15/538/2005</p>
            <h2>JEMAAT EL SHADDAI</h2>
            <p style="font-size: 14px;">Dusun Sanggrahan no. 127, RT04/RW16, Tlogoadi, Mlati, Sleman, Yogyakarta</p>
        </div>
    </div>

    <div class="content">
        {!! $letter->rendered_content !!}
    </div>

    <div class="footer">
        <div class="signature-section">
            <div class="signer">
                <p>Sekretaris,</p>
                <br><br><br>
                <p>( __________________ )</p>
            </div>
            <div class="signer">
                <p>Ketua Majelis,</p>
                <!-- Space for signature -->
                <br><br><br>
                <p>( {{ $letter->approver->name ?? '__________________' }} )</p>
            </div>
        </div>
    </div>

    <div class="qr-code">
        <!-- SVG QR Code -->
        @if(isset($qrCode))
            {!! $qrCode !!}
        @endif
    </div>
</body>
</html>
